from pydantic import BaseModel, Field

from src.schemas.search import SearchResult


class ResearchPlan(BaseModel):
    """Generated by LLM, topic of the query, questions the research process must answer and search queries used in a web search tool later."""
    topic: str
    research_questions: list[str]
    search_queries: list[str]


class ResearchEvidence(BaseModel):
    """Combines the generated plan with the results of the web search tool, cited."""
    plan: ResearchPlan
    sources: list[ResearchSource]


class ResearchSource(BaseModel):
    """Takes the query and web search tools results for that query and appends a source_id."""
    source_id: str
    search_query: str
    result: SearchResult


class ResearchFinding(BaseModel):
    """Generated by the LLM during synthesis research report - uses provided claims for the summary with their source_ids that get verified."""
    claim: str
    source_ids: list[str]


class ResearchReport(BaseModel):
    """Complete research report generated by the LLM."""
    title: str
    summary: str
    findings: list[ResearchFinding]
    limitations: list[str] = Field(default_factory=list)